 * Split a range using golden ratio
 * Major segment = 61.8%, minor = 38.2%
 * @param {number} min
 * @param {number} max
 * @returns {{ major: number, minor: number, split: number }}
 */
function goldenSplit(min, max) {
    const range = max - min;
    const split = min + range * PHI_INV;
    return {
