 * @returns {number[]} harmonic sequence
 */
function phiHarmonics(base, count = 8) {
    const result = [];
    for (let i = 0; i < count; i++) {
        result.push(Math.round(base * Math.pow(PHI, i)));
    }
    return result;
}

