        if (!entry) {
            this.metrics.misses++;
            return undefined;
        }
        if (Date.now() > entry.expiresAt) {
            this.store.delete(key);
            this.metrics.misses++;
            return undefined;
        }
        this.metrics.hits++;
        // Move to end for LRU
        this.store.delete(key);
        this.store.set(key, entry);
        return entry.value;
    }

if (this.state === 'OPEN') {
